rep("$('addAlternative').onclick=()=>update(()=>{p.alternatives.push({id:uid(),name:'New alternative'});p.altComparisons={};});}", """$('addAlternative').onclick=()=>update(()=>{p.alternatives.push({id:uid(),name:'New alternative'});p.altComparisons={};});$('hierarchyEnabled').onchange=el=>update(()=>{initHierarchy();p.hierarchy.enabled=el.target.checked;resetHierarchyComparisons(p);});if(p.hierarchy?.enabled){if($('addGroup'))$('addGroup').onclick=()=>update(()=>{p.hierarchy.groups.push({id:uid(),name:'New group',weight:0});resetHierarchyComparisons(p);});bind('[data-group-name]','change',el=>p.hierarchy.groups.find(g=>g.id===el.dataset.groupName).name=el.value);bind('[data-criterion-group]','change',el=>{p.criteria.find(c=>c.id===el.dataset.criterionGroup).groupId=el.value;resetHierarchyComparisons(p);});bind('[data-delete-group]','click',el=>{const id=el.dataset.deleteGroup;const groups=p.hierarchy.groups;const replacement=groups.find(g=>g.id!==id);if(!replacement)return;for(const c of p.criteria)if(c.groupId===id)c.groupId=replacement.id;p.hierarchy.groups=groups.filter(g=>g.id!==id);resetHierarchyComparisons(p);});}}""")
rep("if(step===1){bind('[name=wm]'", """if(step===1&&p.hierarchy?.enabled){bind('[name=hm]','change',el=>{p.hierarchy.method=el.value;resetHierarchyComparisons(p);});bind('[data-hier-weight]','change',el=>{const [g,id]=el.dataset.hierWeight;const item=g==='root'?p.hierarchy.groups.find(x=>x.id===id):p.criteria.find(x=>x.id===id);item.weight=el.value===''?null:Number(el.value);p.weightAdjustment=null;});document.querySelectorAll('select').forEach(el=>{const key=Object.keys(el.dataset).find(k=>k.startsWith('hierPair'));if(!key)return;el.onchange=()=>update(()=>{const group=key.slice('hierPair'.length).replace(/^./,c=>c.toLowerCase());const gid=group.slice(1);const record=gid==='root'?p.hierarchy.groupComparisons:(p.hierarchy.childComparisons[gid]??={});record[el.dataset[key]]=Number(el.value);p.weightAdjustment=null;});});}
if(step===1&&!p.hierarchy?.enabled){bind('[name=wm]'""")
